  let ty ← Lean.Meta.whnfR ty
  if ty.isAppOfArity `Not 1 = true then do
      let ty ← Lean.Meta.whnfR ty.appArg!
      if ty.isAppOfArity `LT.lt 4 = true then pure (ty.appArg!, ty.appFn!.appArg!, false, false)
        else
          if ty.isAppOfArity `LE.le 4 = true then pure (ty.appArg!, ty.appFn!.appArg!, true, false)
          else failure
    else
      if ty.isAppOfArity `LT.lt 4 = true then pure (ty.appFn!.appArg!, ty.appArg!, true, true)
      else
        if ty.isAppOfArity `LE.le 4 = true then pure (ty.appFn!.appArg!, ty.appArg!, false, true)
        else failure

